message.content:
{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined royal city.",
      "visual_description": "A crumbling stone gatehouse with broken royal banners flapping in the wind, the city's spires visible beyond a misty valley.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings at the outer market.",
      "visual_description": "Huddled figures in tattered cloaks point toward the city walls, their faces pale with fear as shadows move behind broken windows.",
      "characters": ["Townspeople", "Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols block the main gate.",
      "visual_description": "Soldiers in rusted plate armor bearing tarnished royal crests stand rigidly before iron portcullis bars, spears lowered.",
      "characters": ["Patrol Guard", "Patrol Guard", "Patrol Guard"]
    },
    {
      "scene_number": 4,
      "caption": "The party discovers a secret passage beneath a collapsed tower.",
      "visual_description": "A narrow stone stairwell descending into darkness, cobwebs stretching across a half-open iron grate.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 5,
      "caption": "Inside the cursed tower, illusions of treasure appear.",
      "visual_description": "Golden coins and jeweled crowns float in midair, shimmering with a sickly green glow around a spiral staircase.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "Kael resists a phantom of his lost love.",
      "visual_description": "A translucent figure in white reaches out from a mirror, Kael turning away with a pained expression.",
      "characters": ["Kael", "Phantom"]
    },
    {
      "scene_number": 7,
      "caption": "Mira disarms a trap on a magic door.",
      "visual_description": "Runes pulsing red along a stone doorframe, Mira's fingers tracing a counter-rune as sparks fly from a hidden mechanism.",
      "characters": ["Mira", "Elara", "Kael"]
    },
    {
      "scene_number": 8,
      "caption": "The door opens to a grand hall with old royal banners.",
      "visual_description": "Tattered crimson and gold banners hanging from a vaulted ceiling, dust motes dancing in shafts of pale light from broken windows.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 9,
      "caption": "A dragon's roar echoes from the upper floors.",
      "visual_description": "A massive shadow passes across the high windows, scales glinting briefly before the sound of heavy wings fades.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "The party finds the captive in an iron cage.",
      "visual_description": "A figure in chains slumps inside a barred cage suspended from the ceiling, torchlight flickering on cold metal.",
      "characters": ["Elara", "Kael", "Mira", "Captive"]
    },
    {
      "scene_number": 11,
      "caption": "Patrol guards ambush them in the throne room.",
      "visual_description": "Guards burst from behind pillars, swords drawn, banners casting long shadows across a cracked marble throne.",
      "characters": ["Patrol Guard", "Patrol Guard", "Patrol Guard", "Elara", "Kael", "Mira", "Captive"]
    },
    {
      "scene_number": 12,
      "caption": "Elara holds off the guards with a barrier spell.",
      "visual_description": "A shimmering dome of blue light surrounds the party while guards hammer against it with gauntleted fists.",
      "characters": ["Elara", "Kael", "Mira", "Captive", "Patrol Guard", "Patrol Guard"]
    },
    {
      "scene_number": 13,
      "caption": "They flee through a crumbling corridor.",
      "visual_description": "Stone blocks raining from the ceiling as the party runs past shattered statues and falling tapestries.",
      "characters": ["Elara", "Kael", "Mira", "Captive"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door seals behind them, blocking pursuit.",
      "visual_description": "A stone door engraved with swirling runes glows blue and slides shut with a grinding boom, dust puffing from the seams.",
      "characters": ["Elara", "Kael", "Mira", "Captive"]
    },
    {
      "scene_number": 15,
      "caption": "They emerge onto a high bridge overlooking the city.",
      "visual_description": "A narrow stone bridge arching over a fog-filled chasm, the ruined city sprawling behind them under a blood-red sky.",
      "characters": ["Elara", "Kael", "Mira", "Captive"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge begins to collapse behind them.",
      "visual_description": "Stone blocks falling into the mist one by one, cracks racing along the bridge surface as the party runs.",
      "characters": ["Elara", "Kael", "Mira", "Captive"]
    },
    {
      "scene_number": 17,
      "caption": "A final leap to safety on the far cliff.",
      "visual_description": "Kael shoves the captive across a widening gap, then jumps himself as the last section of bridge crumbles away.",
      "characters": ["Kael", "Elara", "Mira", "Captive"]
    },
    {
      "scene_number": 18,
      "caption": "The party watches the city burn in the distance.",
      "visual_description": "Silhouettes of the four figures on a rocky outcrop, the ruined city ablaze with dragon fire behind them, dawn breaking on the horizon.",
      "characters": ["Elara", "Kael", "Mira", "Captive"]
    }
  ]
}

